 1	import java.io.ByteArrayOutputStream;
 2	import java.io.PrintStream;
 3	import java.util.Arrays;
 4	import java.util.List;
 5	
 6	public final class CompatibilityTest {
 7	    private static final String DEMO_OUTPUT = "0 9 12" + System.lineSeparator();
 8	
 9	    private CompatibilityTest() {
10	    }
11	
12	    public static void main(String[] args) {
13	        assertFacadeSearch();
14	        assertMainOutput("KMPSearch main", () -> KMPSearch.main(new String[0]));
15	        assertMainOutput("legacy launcher", () -> kmp_pattern_searching.main(new String[0]));
16	    }
17	
18	    private static void assertFacadeSearch() {
19	        List<Integer> actual = KMPSearch.search("aba", "ababa");
20	        List<Integer> expected = Arrays.asList(0, 2);
21	        if (!actual.equals(expected)) {
22	            throw new AssertionError("Expected facade matches " + expected + ", but got " + actual + ".");
23	        }
24	    }
25	
26	    private static void assertMainOutput(String scenario, Runnable action) {
27	        PrintStream originalOut = System.out;
28	        ByteArrayOutputStream output = new ByteArrayOutputStream();
29	
30	        try {
31	            System.setOut(new PrintStream(output));
32	            action.run();
33	        } finally {
34	            System.setOut(originalOut);
35	        }
36	
37	        String actual = output.toString();
38	        if (!DEMO_OUTPUT.equals(actual)) {
39	            throw new AssertionError("Expected " + scenario + " to print '" + DEMO_OUTPUT + "', but got '"
40	                    + actual + "'.");
41	        }
42	    }
43	}
